sys_atf_step.step_config:
{"script": "(function(outputs, steps, stepResult, assertEqual) {
 var id = steps('criar_agendamento').record_id;
 var out = new RegistrarSessaoUseCase().execute({ agendamentoId: id });
 assertEqual({ name: 'status concluido no retorno', shouldbe: 'concluido', value: out.status });
})(outputs, steps, stepResult, assertEqual);"}
